go.solution:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func sumAllLines(scanner *bufio.Scanner) int {
	total := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		n, _ := strconv.Atoi(line)
		total += n
	}
	return total
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	fmt.Println(sumAllLines(scanner))
}

